head.script:
scwin.onpageload = function() {};
scwin.onpageunload = function() {};
scwin.trigger11_onclick = function(e) {
    for (var i = 0; i < 1; i++) {
        generator1.insertChild(i);
        var tmpChild = generator1.getChild(i, "spinner1");
        tmpChild.setValue(i);
    }
};
scwin.trigger1_onclick = function(e) {
    var generatorIdx = this.getGeneratedIndex();
    var generatorComp = generator1.getChild(generatorIdx, "spinner1");
    alert(generatorComp.getValue());
};
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger11').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('generator1_0_spinner1_upButton').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById($p.id+'generator1_0_spinner1___input').value == '1'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
